const rows=$input.all().map(i=>i.json||{});if(!rows.length)return[];
const c=(v,m=500)=>String(v??'').replace(/[\r\n]/g,' ').replace(/\s+/g,' ').trim().slice(0,m);
const fp=r=>[c(r.event_type,40),c(r.task_code,120),c(r.reason,300),c(r.payload_message,500),c(r.approval_action,200)].join('|');
const f=rows[0],same=rows.filter(r=>fp(r)===fp(f)),ids=same.map(r=>Number(r.id)).filter(Number.isSafeInteger);
const no=c(f.task_number,30),tt=c(f.task_title,140),internal=c(f.task_code||'不明',120),reason=c(f.reason,300),supplied=c(f.payload_message,900),recommended=c(f.recommended_action,500),approval=c(f.approval_action,300),impact=c(f.impact,300);
const commit=/^[0-9a-f]{7,40}$/i.test(String(f.commit_hash||''))?String(f.commit_hash):'';
const label=no&&tt?'Task '+no+'「'+tt+'」':tt?'「'+tt+'」':'タスク特定不可（内部ID: '+internal+'）';
let h,lines;
if(f.event_type==='completed'){h='✅ 開発タスク完了';lines=[supplied||'実装・テスト・commitが完了しました'];if(commit)lines.push('commit: '+commit);}
else if(f.event_type==='anomaly'||f.event_type==='stopped'){h='⚠️ 開発タスク停止';lines=['停止理由: '+(reason||'正常完了前に終了しました'),'作業データ: 差分・worktreeは保全済み','自動対応: 安全確認が必要なため停止中','次のアクション: '+(recommended||(no?'このメッセージへ「OK Task '+no+'」と返信してください。チャッピーが現状を再確認してから安全に再開します。':'情報不足のため承認せず、この内部IDをチャッピーへ送って確認してください。'))];}
else{h='🟡 承認待ち';lines=['承認対象: '+(approval||supplied||'具体的な操作を取得できませんでした'),'必要理由: '+(reason||'人間の確認が必要と判定されました')];if(impact)lines.push('承認時の影響: '+impact);lines.push('次のアクション: '+(recommended||(no?'内容に問題がなければ、このメッセージへ「OK Task '+no+'」と返信してください。':'情報不足のため承認せず、この内部IDをチャッピーへ送って確認してください。')));}
if(same.length>1)lines.push('重複 '+same.length+'件は1件にまとめました');
const text='<@U0BQJV2740J> '+[h,label,...lines].join('\n');
const blocks=[{type:'header',text:{type:'plain_text',text:h,emoji:true}},{type:'section',text:{type:'mrkdwn',text:'<@U0BQJV2740J>\n*'+label.replace(/[*_~]/g,'')+'*\n'+lines.map(x=>'• '+x).join('\n')}}];
return[{json:{outbox_ids:ids.join(','),text:text.slice(0,2800),blocks}}];

parameters.query:
UPDATE task_dispatcher_outbox SET delivered_at=NOW()
WHERE delivered_at IS NULL
AND FIND_IN_SET(id,'{{ $('Slack用に内容と次の行動を整形').item.json.outbox_ids }}')>0;

